//! Original Spargus shrubs, from wascitya-background.glb, material
//! wascity-shrub-orange-01. Each tuft retains three native twenty-triangle
//! fronds and their UVs; only translation and uniform scale fit the block.
//! The opaque texture needs these leaf silhouettes, never crossed rectangles.
use serde_json::json;

pub const MODELS: &[fn() -> String] = &[one, two, three];
fn one() -> String { model(0) }
fn two() -> String { model(1) }
fn three() -> String { model(2) }
fn model(kind: usize) -> String {
    SHRUBS[kind].iter().map(|tri| {
        let positions=tri.map(|v|[v[0],v[1],v[2]]);
        let uv=tri.map(|v|[v[3],v[4]]);
        let from=std::array::from_fn::<_,3,_>(|axis|positions.iter().map(|p|p[axis]).fold(f32::INFINITY,f32::min));
        let to=std::array::from_fn::<_,3,_>(|axis|positions.iter().map(|p|p[axis]).fold(f32::NEG_INFINITY,f32::max));
        json!({"from":from,"to":to,"shade_direction_override":"up",
            "faces":{"up":{"texture":"#plant","iw4l_triangle":{"positions":positions,"uv":uv,"double_sided":true}}}}).to_string()
    }).collect::<Vec<_>>().join(",")
}

